<?php session_start();if(!isset($_SESSION['user_id'])){header('Location:login.php');exit;}require_once '../config/database.php';$id=(int)$_GET['id'];$q=$pdo->prepare('SELECT * FROM tickets WHERE id=? AND user_id=?');$q->execute([$id,$_SESSION['user_id']]);$t=$q->fetch();if(!$t)exit('Ticket not found');if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('INSERT INTO ticket_messages(ticket_id,sender_id,message) VALUES(?,?,?)');$q->execute([$id,$_SESSION['user_id'],trim($_POST['message'])]);header('Location:chat.php?id='.$id);exit;}$q=$pdo->prepare('SELECT m.*,u.name FROM ticket_messages m LEFT JOIN users u ON u.id=m.sender_id WHERE ticket_id=? ORDER BY m.id');$q->execute([$id]);$ms=$q->fetchAll();?><!doctype html><html><body style="font-family:Arial;background:#f4f7fb"><main style="max-width:900px;margin:auto;padding:25px"><a href="tickets.php">← My Tickets</a><h2><?=htmlspecialchars($t['ticket_no'])?> - <?=htmlspecialchars($t['subject'])?></h2><div style="background:#e9eef5;padding:20px;height:400px;overflow:auto"><?php foreach($ms as $m):?><div style="background:white;padding:10px;margin:8px;border-radius:10px"><b><?=htmlspecialchars($m['name']??'User')?></b><br><?=nl2br(htmlspecialchars($m['message']))?></div><?php endforeach;?></div><form method="post"><textarea name="message" required rows="4" style="width:100%;margin-top:10px"></textarea><button>Send Reply</button></form></main></body></html>